  "summary": "The code contains critical security vulnerabilities including LDAP injection and lack of authentication, alongside severe performance issues due to unmanaged connections. Overall code health is poor, requiring refactoring for security, resource management, and modularity.",
  "fixed_code": "import os\nimport ldap\nimport ldap.filter\nfrom flask import request, Flask, abort\n\napp = Flask(__name__)\n\ndef get_ldap_user(dc: str, username: str):\n    ldap_url = os.getenv('LDAP_URL', 'ldaps://127.0.0.1')\n    ldap_connection = ldap.initialize(ldap_url)\n    try:\n        ldap_connection.start_tls_s()\n        safe_dc = ldap.dn.escape_dn_chars(dc)\n        safe_filter = ldap.filter.filter_format('(user=%s)', [username])\n        dn = f'dc={safe_dc}'\n        return ldap_connection.search_s(dn, ldap.SCOPE_SUBTREE, safe_filter)\n    finally:\n        ldap_connection.unbind_s()\n\n@app.route(\"/normal\")\ndef normal() -> str:\n    dc = request.args.get('dc')\n    username = request.args.get('username')\n    if not dc or not username:\n        abort(400, \"Missing required parameters\")\n    \n    try:\n        user = get_ldap_user(dc, username)\n        return str(user)\n    except ldap.LDAPError as e:\n        return str(e), 500"
